"""Weekly timesheet rows built from a list of shifts."""

from typing import List

from hourglass.models import Shift


def _totals(shifts):
    totals = {}
    for shift in shifts:
        if not shift.worker.strip():
            raise ValueError("blank worker name")
        count, mins = totals.get(shift.worker, (0, 0))
        mins += shift.span.minutes
        totals[shift.worker] = (count + 1, mins)
    return totals


def _busy(item):
    name, (count, mins) = item
    return (-mins, name)


def _line(name, count, mins):
    return f"{name}: {count} shifts, {mins / 60:.1f} hours"


# ---
def timesheet_rows(shifts: List[Shift]) -> List[str]:
    """One line per worker, most hours first."""
    if not shifts:
        raise ValueError("no shifts")
    totals = _totals(shifts)
    order = sorted(totals.items(), key=_busy)
    return [_line(name, *t) for name, t in order]
